import {openCopilot} from './ai-ui.mjs';
import {servicePanel,deliveryFields,deliveryPayload,serviceAction} from './kpi-ui.mjs';
import {shiftDate,localToday} from './logistics-kpis.mjs';
import {hydrateState} from './enhancements.mjs';
import {directorPanel,masterView,noteWorkbench,enhancementAction} from './enhancement-ui.mjs';
import {seed,VERSION,total,ready,compatible,truckOptions,verified,gates,command,draft,demoDate} from './engine.mjs';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format(n);
const icons={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',box:'m3 7 9-5 9 5v10l-9 5-9-5V7Z M3 7l9 5 9-5 M12 12v10',truck:'M3 5h11v12H3z M14 9h4l3 4v4h-7 M7 20a2 2 0 1 0 0-4 2 2 0 0 0 0 4 M18 20a2 2 0 1 0 0-4 2 2 0 0 0 0 4',scan:'M3 8V3h5 M16 3h5v5 M21 16v5h-5 M8 21H3v-5 M7 8v8 M10 7v10 M14 7v10 M17 8v8 M2 12h20',shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6l-9-4Z m-5 10 3 3 6-6',file:'M5 2h9l5 5v15H5V2Z M14 2v6h5 M8 12h8 M8 16h8',return:'M9 4 4 9l5 5 M4 9h10a6 6 0 1 1 0 12h-2',chart:'M3 3v18h18 M7 16v-4 M12 16V8 M17 16V5',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',arrow:'M4 12h16 m-6-6 6 6-6 6',plus:'M12 5v14 M5 12h14',chevron:'m9 6 6 6-6 6',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14 m5 12 6 6',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',leaf:'M4 18C1 5 12 2 21 3c1 12-8 18-17 15 m0 0L16 7',alert:'m12 3 10 18H2L12 3Z M12 9v4 M12 16v1',check:'m5 12 4 4L19 6',calendar:'M4 5h16v16H4z M8 2v6 M16 2v6 M4 10h16',help:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M9 9a3 3 0 0 1 6 0c0 2-3 2-3 5 M12 17v1',mail:'M3 5h18v14H3z M3 5l9 7 9-7',map:'m3 5 6-3 6 3 6-3v17l-6 3-6-3-6 3V5Z M9 2v17 M15 5v17'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.box}"/></svg>`;
let state;try{state=JSON.parse(localStorage.getItem(VERSION)||localStorage.getItem('sipgreen-demo-v3')||'null')||seed();if(state.schema===VERSION||state.schema==='sipgreen-demo-v3')state.schema=VERSION;else state=seed();}catch{state=seed();}
state=hydrateState(state);let serviceAsOf=shiftDate(localToday(),-1);let directorFilters={principal:'',warehouse:''};
let role='planner',page='overview',activeShipment=state.shipments[0].id,selected=new Set(),globalSearch='',filterPrincipal='',filterWarehouse='';
const principal=id=>state.principals.find(x=>x.id===id);const wh=id=>state.warehouses.find(x=>x.id===id);const shipment=()=>state.shipments.find(s=>s.id===activeShipment)||state.shipments[0];
const badge=(text,kind='')=>`<span class="badge ${kind}"><span style="font-size:7px">●</span>${esc(text)}</span>`;
const statusBadge=s=>badge(s.status,s.status==='In transit'?'blue':s.status==='Preparing'?'amber':s.status==='Closed'?'gray':'');
function toast(message,error=false){const t=$('#toast');t.textContent=message;t.className=`show${error?' error':''}`;clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.className='',5000);}
function run(type,p={}){try{const out=command(state,type,{shipment:activeShipment,...p},role);localStorage.setItem(VERSION,JSON.stringify(out.state));state=out.state;render();return out;}catch(e){if($('#modal')?.open&&$('#formerror'))$('#formerror').textContent=e.message;toast(e.message,true);return null;}}
const button=(text,action,kind='',extra='')=>`<button class="btn ${kind}" data-action="${action}" ${extra}>${text}</button>`;
const field=(label,name,value='',type='text',hint='')=>`<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?'min="0" step="1"':''} required>${hint?`<small>${hint}</small>`:''}</div>`;
const textfield=(label,name,value='',hint='')=>`<div class="field"><label for="${name}">${label}</label><textarea id="${name}" name="${name}" required>${esc(value)}</textarea>${hint?`<small>${hint}</small>`:''}</div>`;
const nav=[['overview','grid','Overview'],['planning','box','Shipment planning'],['shipments','truck','Shipments'],['scanning','scan','Warehouse & scans'],['approvals','shield','Approvals'],['documents','file','Documents'],['returns','return','Customer returns'],['masters','settings','Fleet & materials'],['costs','chart','Trip costs'],['audit','clock','Audit trail'],['guide','help','Project guide']];
function shell(content){const approvals=state.shipments.filter(s=>(s.partialRequest&&!s.partialApproval)||(s.manualRequest&&!s.manualApproval)).length;return `<aside class="sidebar"><div class="brand"><img src="./mark.svg" alt=""><div><strong>Last Mile Logistics</strong><span>LOGISTICS WORKSPACE</span></div></div><div class="workspace"><div class="avatar">LM</div><div><b>3PL Control Tower</b><small>Multi-principal operations</small></div></div><div class="eyebrow">Workspace</div><nav>${nav.map(([id,i,label],idx)=>`${idx===8?'<div class="navspacer"></div>':''}<button data-page="${id}" class="${page===id?'active':''}" title="${label}">${icon(i)}<span>${label}</span>${id==='approvals'&&approvals?`<small class="count">${approvals}</small>`:''}</button>`).join('')}</nav><div class="sidebottom"><div class="pilot"><div class="row"><b class="small">Built for accountable moves.</b>${icon('leaf')}</div><p>Every unit. Every handoff.<br>A clearer delivery journey.</p><button data-page="guide">Explore the project →</button></div><div class="profile"><div class="avatar">LM</div><div><b>Last Mile Logistics operations</b><span>Synthetic demonstration</span></div></div></div></aside><main class="main"><header class="topbar"><div class="crumb">Workspace ${icon('chevron')} <b>${nav.find(x=>x[0]===page)?.[2]}</b><select id="mobilepage" class="mobilepage" aria-label="Workspace page">${nav.map(([id,,label])=>`<option value="${id}" ${page===id?'selected':''}>${label}</option>`).join('')}</select></div><div class="topright"><form class="search" id="global-search">${icon('search')}<input name="q" aria-label="Find a shipment" placeholder="Find a shipment…" value="${esc(globalSearch)}"><kbd>↵</kbd></form><span class="divider"></span><span class="demo-pill"><span class="dot"></span>Demo workspace</span><label class="sr-only" for="role">Demonstration role</label><select class="roleSelect" id="role" title="Simulate an operator role; not authentication">${[['planner','Planner · OP-01'],['warehouse','Warehouse · WH-01'],['checker','Checker · QC-02'],['manager','Manager · MGR-01'],['accounts','Accounts · ACC-01']].map(([id,label])=>`<option value="${id}" ${role===id?'selected':''}>${label}</option>`).join('')}</select></div></header><div class="content">${content}<footer class="footnote"><span>Last Mile Logistics · Logistics execution, with accountability built in.</span><span>Synthetic data · Browser-local demo · No external sends</span></footer></div></main>`;}
function heading(title,subtitle,actions=''){return `<div class="heading"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="buttons">${actions}</div></div>`;}
function selectors(){return `<div class="filterbar"><label class="sr-only" for="shipselect">Active shipment</label><select id="shipselect">${state.shipments.map(s=>`<option value="${s.id}" ${activeShipment===s.id?'selected':''}>${s.id} · ${esc(principal(s.principal).short)} · ${esc(s.status)}</option>`).join('')}</select><span class="spacer"></span>${badge('Principal-owned stock','gray')}${badge('Manual transporter handoff','gray')}</div>`;}
function checklist(items){return items.map(([ok,text])=>`<div class="check ${ok?'ok':''}"><span class="status-icon">${ok?'✓':'!'}</span><span>${esc(text)}</span></div>`).join('');}
function overview(){const preparing=state.shipments.filter(s=>!s.dispatched).length,intransit=state.shipments.filter(s=>s.status==='In transit').length,delivered=state.shipments.filter(s=>s.delivery).length,openreturns=state.returns.filter(r=>r.status!=='Closed').length,units=state.shipments.filter(s=>!s.dispatched).reduce((n,s)=>n+total(s,'packed'),0);return heading('Operations overview','A clear view of every shipment, from ready PO to reconciled delivery.',button(icon('download')+' Export summary','export')+button(icon('plus')+' Plan shipment','goPlanning','primary'))+`<div class="notice">${icon('shield')}<span>Demonstration environment. Sample data is saved in this browser; role switching is not production authentication.</span><button data-page="guide">View project scope →</button></div><section class="hero"><div><div class="eyebrow">THE RIGHT GOODS. THE RIGHT DESTINATION.</div><h2>Keep your next move<br>on the right track.</h2><p>${preparing} shipments preparing · ${units} units planned · ${state.warehouses.length} warehouses connected</p><button class="link" data-page="scanning">Open warehouse workspace &nbsp; ↗</button></div><div class="hero-route"><div class="eyebrow">Featured route · sample</div><div class="route-line"><span class="route-node"></span><span class="route-dash"><span class="route-truck">${icon('truck')}</span></span><span class="route-node end"></span></div><div class="route-labels"><span>Bhiwandi DC</span><span>Pune FC</span></div><div class="route-foot"><span>Departure-led planning</span><span>2 day route estimate</span></div></div></section><div class="kpis">${[[state.shipments.length,'Total shipments','truck','In this demonstration'],[intransit,'In transit','map','Awaiting delivery evidence'],[preparing,'Preparing to dispatch','box','Scan and document verification'],[openreturns,'Open customer returns','return','Receipt and reconciliation']].map(([n,l,i,sub])=>`<div class="card kpi"><div class="kpi-top">${l}${icon(i)}</div><div class="metric">${String(n).padStart(2,'0')}</div><div class="kpi-foot">${sub}</div></div>`).join('')}</div>${servicePanel(state,directorFilters,serviceAsOf)}${directorPanel(state,directorFilters)}<div class="grid2"><section class="card"><div class="section-head"><div><h2>Shipment pipeline</h2><p>From a planned departure to a confirmed outcome.</p></div>${badge('Current sample')}</div><div class="stage-grid">${[[state.orders.filter(o=>ready(state,o)>0).length,'Ready POs','box','planning'],[preparing,'Preparing','scan','scanning'],[intransit,'In transit','truck','shipments'],[delivered,'Delivered','check','costs']].map(([n,l,i,p])=>`<div class="stage">${icon(i)}<strong>${String(n).padStart(2,'0')}</strong><span>${l}</span><button data-page="${p}" aria-label="Open ${l}"></button></div>`).join('')}</div></section><section class="card"><div class="section-head"><div><h2>Attention required</h2><p>Resolve the gaps before goods leave.</p></div>${icon('alert')}</div><div class="alert">${icon('scan')}<div><b>Physical verification pending</b><p>${preparing} preparing shipments need unit scans and sealed carton links.</p></div><button data-page="scanning" aria-label="Open scans">↗</button></div><div class="alert" style="background:#f0f4e9">${icon('shield')}<div><b>Principal approval, preserved</b><p>Short shipments need permission email evidence and a manager decision.</p></div><button data-page="approvals" aria-label="Open approvals">↗</button></div></section></div><section class="card"><div class="section-head"><div><h2>Active shipments</h2><p>Owner, route and readiness in one place.</p></div><button class="textlink" data-page="shipments">View all shipments ↗</button></div>${shipmentTable(state.shipments.slice(0,5))}<div class="tablefoot"><span>Showing ${Math.min(state.shipments.length,5)} of ${state.shipments.length} shipments</span><span>Stock ownership stays with the principal</span></div></section>`;}
function shipmentTable(list){return `<div class="tablewrap"><table><thead><tr><th>SHIPMENT / PRINCIPAL</th><th>ORIGIN → DESTINATION</th><th>DEPARTURE</th><th>VERIFIED UNITS</th><th>STATUS</th><th></th></tr></thead><tbody>${list.map(s=>`<tr><td><b>${s.id}</b><small>${esc(principal(s.principal).name)}</small></td><td>${esc(wh(s.warehouse).name)}<small>${esc(s.destination)}</small></td><td>${s.departure}<small>ETA ${eta(s)}</small></td><td>${s.scans.length} / ${total(s,'packed')}<div class="progress"><i style="width:${Math.min(100,s.scans.length/Math.max(total(s,'packed'),1)*100)}%"></i></div></td><td>${statusBadge(s)}</td><td><button class="circlebutton" data-open="${s.id}" aria-label="Open ${s.id}">↗</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No shipments match these filters.</td></tr>'}</tbody></table></div>`;}
function eta(s){const d=new Date(`${s.departure}T12:00:00`);d.setDate(d.getDate()+s.leadDays);return d.toISOString().slice(0,10);}
function planning(){const orders=state.orders.filter(o=>ready(state,o)>0),picked=orders.filter(o=>selected.has(o.id));let opts=[];try{if(picked.length)opts=truckOptions(state,picked.map(o=>({sku:o.sku,planned:ready(state,o)})),{route:picked[0].route,principal:picked[0].principal});}catch{}return heading('Shipment planning','Approved, stock-backed POs. Procurement stays outside this logistics flow.',button(icon('help')+' Planning rules','planningRules'))+`<div class="twocol"><section class="card"><div class="section-head"><div><h2>Ready purchase orders</h2><p>Existing active shipment commitments are already excluded.</p></div><span class="selected-count">${selected.size} selected</span></div><div class="tablewrap"><table><thead><tr><th></th><th>ORDER / PRINCIPAL</th><th>ROUTE / SKU</th><th>READY</th></tr></thead><tbody>${orders.map(o=>`<tr><td><input type="checkbox" class="ordercheck" value="${o.id}" aria-label="Select ${o.id}" ${selected.has(o.id)?'checked':''}></td><td><b>${o.id}</b><small>${esc(principal(o.principal).short)} · ${esc(wh(o.warehouse).name)}</small></td><td>${esc(o.route)}<small>${o.sku} · ${esc(o.platform)}</small></td><td><b>${ready(state,o)}</b> units</td></tr>`).join('')||'<tr><td colspan="4" class="empty">All ready quantities are committed.</td></tr>'}</tbody></table></div><div class="help" style="margin:18px">Grouping checks principal, origin, destination, platform and category. Cross-principal co-loading is disabled.</div></section><section class="card padded"><h2>Build a departure plan</h2><p>Choose compatible orders, then review capacity and quoted freight.</p>${picked.length?`<div class="notice">${icon(compatible(picked)?'check':'alert')}${compatible(picked)?'Selected POs are compatible.':'Incompatible POs: regroup before planning.'}</div>${opts.map((t,i)=>`<label class="truckcard ${i===0?'chosen':''}"><input type="radio" name="truck" value="${t.id}" ${i===0?'checked':''} ${!t.fit?'disabled':''}><div><b>${t.name}</b><p>${t.weight.toFixed(1)} / ${t.capacity} kg · ${t.volumeUsed.toFixed(2)} / ${t.volume} m³</p><p>${t.freightPct.toFixed(1)}% of sample goods value · indicative rate</p>${t.weight/t.capacity<.2&&t.volumeUsed/t.volume<.2?'<p style="color:#a07836">Low utilization — review consolidation before departure.</p>':''}</div><b>${money(t.rate)}</b></label>`).join('')}${field('Planned warehouse departure','departure',demoDate(),'date','Dispatch day, not a receiving slot.')}${button(icon('plus')+' Confirm departure plan','confirmPlan','primary',compatible(picked)?'':'disabled')} ${button('AI explain this plan','ai:plan','',compatible(picked)?'':'disabled')}`:'<div class="scanbox">'+icon('box')+'<h3>Select ready POs</h3><p>Truck fit and estimated freight appear here.</p></div>'}<div class="help">Rates, lead times and stock are synthetic. Capacity checks are not a physical loading guarantee.</div></section></div>`;}
function shipments(){const list=state.shipments.filter(s=>(!filterPrincipal||s.principal===filterPrincipal)&&(!filterWarehouse||s.warehouse===filterWarehouse)&&(!globalSearch||JSON.stringify([s.id,s.destination,principal(s.principal).name]).toLowerCase().includes(globalSearch.toLowerCase())));return heading('Shipments','Planned dates and actual events stay distinct.',button(icon('plus')+' Plan shipment','goPlanning','primary'))+`<div class="filterbar"><select id="principalfilter" aria-label="Filter principal"><option value="">All principals</option>${state.principals.map(p=>`<option value="${p.id}" ${filterPrincipal===p.id?'selected':''}>${esc(p.short)}</option>`).join('')}</select><select id="warehousefilter" aria-label="Filter warehouse"><option value="">All warehouses</option>${state.warehouses.map(w=>`<option value="${w.id}" ${filterWarehouse===w.id?'selected':''}>${esc(w.name)}</option>`).join('')}</select><span class="spacer"></span>${badge(`${list.length} shipments`,'gray')}</div><section class="card">${shipmentTable(list)}</section>`;}
function shipmentSummary(s){const v=s.scans.length+(s.manualApproval?.revision===s.revision?s.manualApproval.items.reduce((n,l)=>n+l.quantity,0):0);return `<div class="card padded"><div class="row"><h3>${s.id}</h3>${statusBadge(s)}</div><p class="route-mini">${esc(s.route)} · ${esc(principal(s.principal).short)}</p><div class="statlist"><div class="row"><span>Planned / packed</span><b>${total(s)} / ${total(s,'packed')} units</b></div><div class="row"><span>Verified quantity</span><b>${v} / ${total(s,'packed')}</b></div><div class="row"><span>Departure / ETA</span><b>${s.departure} / ${eta(s).slice(5)}</b></div><div class="row"><span>Principal contract</span><b>${esc(principal(s.principal).contract)}</b></div></div><div class="buttons">${button('Transport details','transport','smallbtn')}${button('Message template','draft','smallbtn')}${button('AI transporter draft','ai:transporter','smallbtn')}${button('AI shipment explanation','ai:shipment','smallbtn')}</div></div>`;}
function scanning(){const s=shipment(),issues=gates(state,s);return heading('Warehouse & scans','Verify each product, link its carton, then release against the approved manifest.')+selectors()+`<div class="twocol"><div class="stack"><section class="card padded"><div class="row"><h2>Product verification</h2>${badge('Unit → carton / pallet','gray')}</div><div class="scanbox">${icon('scan')}<h3>Every unit has a traceable identity.</h3><p>Scan a serialized product QR, then seal its carton or pallet.</p></div><form id="scanform"><div class="field"><label for="scan-code">Product QR / scanner input</label><input id="scan-code" name="code" class="scaninput" placeholder="${s.lines[0].sku}-U-0001" autocomplete="off" ${s.dispatched?'disabled':''}><small>Demo format: ${s.lines[0].sku}-U-0001. A hardware scanner can type into this field. No camera or IoT connection is claimed.</small></div><div class="buttons"><button class="btn primary" ${s.dispatched?'disabled':''}>${icon('scan')} Verify product</button>${button('Insert next sample code','sampleCode','','type="button" '+(s.dispatched?'disabled':''))}${button('Seal carton / pallet','seal','','type="button" '+(s.dispatched?'disabled':''))}</div></form><div class="line"></div><div class="row"><h3>Physical confirmation</h3>${button('Adjust packed quantity','packed','smallbtn',s.dispatched?'disabled':'')}</div><p class="small muted" style="margin-top:9px">A short pack requires principal permission and a manager decision. Printed labels are not verification.</p><div class="buttons" style="margin-top:14px">${button('Scanner failure / manual request','requestManual','smallbtn',s.dispatched?'disabled':'')}</div></section><section class="card"><div class="section-head"><h2>Product & carton events</h2>${badge(`${s.scans.length} unit scans`,'gray')}</div><div class="tablewrap"><table><thead><tr><th>IDENTIFIER</th><th>SKU / TYPE</th><th>LINK / OPERATOR</th></tr></thead><tbody>${s.scans.slice(-10).reverse().map(u=>`<tr><td><b>${esc(u.code)}</b></td><td>${u.sku} · unit</td><td>${esc(s.cartons.find(c=>c.units.includes(u.code))?.code||'Not yet sealed')}<small>${u.actor}</small></td></tr>`).join('')}${s.cartons.map(c=>`<tr><td><b>${esc(c.code)}</b></td><td>Carton / pallet</td><td>${c.units.length} linked products${c.manual?' + manual reconciliation':''}<small>Aggregation only · no stock increment</small></td></tr>`).join('')||(!s.scans.length?'<tr><td colspan="3" class="empty">No scans yet. Verify a product to begin.</td></tr>':'')}</tbody></table></div></section></div><div class="stack">${shipmentSummary(s)}<section class="card padded"><h2>Dispatch readiness</h2><p>All gates apply before the stock movement.</p>${s.masterReviewRequired?`<div class="help">Master data changed. A Planner or Manager must review this load before dispatch.</div>${button('Review master changes','enh:reviewMaster','smallbtn')}`:''}${s.dispatched?checklist([[true,'Dispatched. Preparation and verification are locked.']]):checklist([[!!s.vehicle&&!!s.driver&&!!s.transporter,'Transporter, vehicle & driver recorded'],[gates(state,s).every(x=>!x.includes('Every packed')),'Packed quantities independently verified'],[s.cartons.length>0&&s.scans.every(u=>s.cartons.some(c=>c.units.includes(u.code))),'Scanned products linked to carton/pallet'],[!s.lines.some(l=>l.packed<l.planned)||s.partialApproval?.revision===s.revision,'Principal permission & approval for any short pack'],[docValidUI(s,'invoice')&&docValidUI(s,'eway')&&docValidUI(s,'lr'),'Required documents uploaded and verified']])}<div class="buttons" style="margin-top:18px">${button(icon('truck')+' Dispatch shipment','dispatch','primary',s.dispatched||issues.length?'disabled':'')}${button('Open documents','goDocuments')}</div>${!s.dispatched?`<p class="small muted" style="margin-top:12px">${issues.length} unresolved ${issues.length===1?'gate':'gates'}. Role: Warehouse or Manager.</p>`:''}</section></div></div>`;}
function docValidUI(s,k){const d=s.documents.find(d=>d.kind===k);return !!(d&&d.data&&d.verified&&d.quantity===total(s,'packed'));}
function approvals(){const s=shipment();return heading('Approvals & exceptions','Preserve the principal’s permission and the 3PL manager’s decision.')+selectors()+`<div class="twocol"><div class="stack"><section class="card padded"><div class="row"><h2>Partial dispatch approval</h2>${badge(s.partialApproval?'Approved':s.partialRequest?.status|| (s.partialRequest?'Awaiting manager':'No request'),s.partialRequest&&!s.partialApproval?'amber':'gray')}</div><p>Commercial urgency is context for a human decision, never an automatic override.</p>${checklist([[s.lines.some(l=>l.packed<l.planned),`Packed ${total(s,'packed')} against ${total(s)} planned units`],[!!s.partialRequest,'Operator request with shortfall and urgency'],[!!s.documents.find(d=>d.kind==='approval'),'Principal permission email attached'],[s.partialApproval?.revision===s.revision,'Manager decision matches current quantities']])}${s.partialRequest?`<div class="help">${esc(s.partialRequest.reason)}</div>`:''}${s.partialApproval?`<div class="help">Approved by ${s.partialApproval.actor}: ${esc(s.partialApproval.reason)}<br>Email reference: ${esc(s.partialApproval.email)}</div>`:''}<div class="buttons" style="margin-top:18px">${button('Request partial dispatch','requestPartial','',s.dispatched?'disabled':'')}${button('Attach principal email','approvalEmail','',s.dispatched?'disabled':'')}${button('Manager decision','approvePartial','primary',s.dispatched?'disabled':'')}${button('Reject / hold','rejectPartial','danger',s.dispatched?'disabled':'')}</div></section><section class="card padded"><div class="row"><h2>Scanner incident & reconciliation</h2>${badge(s.manualApproval?'Approved':s.manualRequest?'Open incident':'No incident',s.manualRequest&&!s.manualApproval?'amber':'gray')}</div><p>Manual quantities stay visibly manual. Carton scans never duplicate product counts.</p>${checklist([[!!s.manualRequest,'Warehouse records failure and evidence reference'],[!!s.manualRequest?.checkedBy,'Independent checker verifies identity and count'],[s.manualApproval?.revision===s.revision,'Manager authorizes the reconciled exception']])}${s.manualRequest?`<div class="help">Incident: ${esc(s.manualRequest.reason)}<br>${s.manualRequest.checkedBy?'Reconciled by '+s.manualRequest.checkedBy+': '+esc(s.manualRequest.checkReason):'Independent reconciliation pending.'}</div>`:''}<div class="buttons" style="margin-top:18px">${button('Record scanner incident','requestManual','',s.dispatched?'disabled':'')}${button('Independent verification','verifyManual','',s.dispatched?'disabled':'')}${button('Approve manual exception','approveManual','primary',s.dispatched?'disabled':'')}</div></section></div><div class="stack">${shipmentSummary(s)}<section class="card padded"><h2>Who can approve?</h2><p>Switch the demonstration role in the top bar to exercise each responsibility.</p>${checklist([[true,'Planner / Warehouse: request a partial shipment'],[true,'Checker: independently reconcile a scanner failure'],[true,'Manager: approve the current shipment version'],[true,'Accounts / Manager: verify document evidence']])}<div class="help">Role switching is a workflow simulation. Production requires authenticated server permissions and a durable audit trail.</div></section></div></div>`;}
const doctypes=[['invoice','Sales invoice','Prepared by 3PL; issuer is recorded explicitly.'],['eway','E-way evidence','Required in this sample; real applicability needs approved rules.'],['lr','LR / Bilty','Required for this sample external-transporter journey.'],['approval','Principal permission email','Required before manager approval of short dispatch.'],['pod','Proof of delivery','Required before recording delivery.']];
function documents(){const s=shipment();return heading('Documents & evidence','Attach retrievable content and record verification.')+selectors()+`<div class="twocol"><section class="card"><div class="section-head"><h2>Shipment document register</h2>${badge('Files ≤ 1 MB','gray')}</div>${doctypes.map(([kind,label,description])=>{const d=s.documents.find(d=>d.kind===kind);return `<div class="document"><span class="fileicon">${icon(kind==='approval'?'mail':'file')}</span><div><b>${label}</b><p>${esc(d?d.reference+' · '+d.name:description)}</p><p>${d?`${d.sample?'Synthetic sample · ':''}${d.quantity} packed units · ${d.verified?'Verified by '+d.verifier:'Not verified'}`:'No file attached'}</p></div><div class="buttons">${d?button('View','viewDoc','smallbtn',`data-kind="${kind}"`):''}${button(d?'Replace':'Attach','uploadDoc','smallbtn',`data-kind="${kind}"`)}${d&&!d.verified?button('Verify','verifyDoc','smallbtn',`data-kind="${kind}"`):d?.verified?badge('Verified'):''}</div></div>`;}).join('')}<div class="tablefoot">Browser-local files. Do not upload confidential records.</div></section><div class="stack">${shipmentSummary(s)}<section class="card padded"><h2>Document checks</h2><p>Rule checks stay authoritative. AI can summarize gaps and user-pasted extracts; no automatic OCR is performed.</p>${button('AI document-gap summary','ai:documents','smallbtn')}${checklist(doctypes.filter(([k])=>['invoice','eway','lr'].includes(k)).map(([k,label])=>[docValidUI(s,k),`${label}: retrievable, current quantity, verified`]))}<div class="help">Checks establish file presence, recorded quantity and review status. They do not authenticate signatures or certify legal validity.</div></section></div></div>`;}
function returnsPage(){return heading('Customer returns','Receive, inspect and reconcile. Vendor returns stay outside scope.',button(icon('plus')+' Open customer return','openReturn','primary'))+`<div class="notice">${icon('return')}<span>Principal-owned goods. Only inspected usable units restore available stock.</span></div><section class="card"><div class="section-head"><h2>Return cases</h2>${badge(`${state.returns.length} cases`,'gray')}</div><div class="tablewrap"><table><thead><tr><th>CASE / SHIPMENT</th><th>PRINCIPAL / SKU</th><th>EXPECTED</th><th>INSPECTION</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody>${state.returns.map(r=>`<tr><td><b>${r.id}</b><small>${r.shipment}</small></td><td>${esc(principal(r.principal).short)}<small>${r.sku}</small></td><td>${r.expected} units</td><td>${r.received===null?'Awaiting receipt':`${r.usable} usable · ${r.damaged} damaged · ${r.missing} missing`}</td><td>${badge(r.status,r.status==='Closed'?'':'amber')}</td><td>${r.status==='Awaiting receipt'?button('Receive & inspect','inspectReturn','smallbtn',`data-return="${r.id}"`):r.status!=='Closed'?button('Reconcile note','settleReturn','smallbtn',`data-return="${r.id}"`):button('View outcome','viewReturn','smallbtn',`data-return="${r.id}"`)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No returns yet. Record delivery with returned quantities, then open a linked case.</td></tr>'}</tbody></table></div></section>${noteWorkbench(state,{button,badge})}<div class="guidegrid" style="margin-top:20px"><section class="card"><span class="number">01 / QUANTITY CONTROL</span><h3>No return without a source.</h3><p>Return quantity is capped by the shipment’s declared returned goods. Only inspected usable goods restore stock. Repeated inspection cannot post stock again.</p></section><section class="card"><span class="number">02 / COMMERCIAL RECONCILIATION</span><h3>Prepared by 3PL, issuer explicit.</h3><p>Record credit/debit-note perspective, issuer, reference, amount and outcome. Prepare and download a draft note, review it as Manager, then reconcile it. No statutory issuance or Tally posting occurs.</p></section></div>`;}
function costsPage(){const s=shipment(),actual=s.costs?Object.values(s.costs).reduce((a,b)=>a+b,0):null,v=s.costs?s.costs.freight-s.estimate:null;return heading('Delivery & trip costs','Confirm the outcome, compare like-for-like costs and close obligations.')+selectors()+`<div class="twocol"><div class="stack"><section class="card padded"><div class="row"><h2>Delivery outcome</h2>${statusBadge(s)}</div><p>Actual departure: ${s.actualDeparture?new Date(s.actualDeparture).toLocaleString('en-IN'):'Not recorded'} · ETA ${eta(s)} (route estimate)</p>${s.delivery?`<div class="kpis" style="grid-template-columns:1fr 1fr"><div class="kpi" style="background:#f3f7eb;border-radius:9px"><div class="eyebrow">Accepted</div><div class="metric">${s.delivery.accepted}<small> units</small></div></div><div class="kpi" style="background:#fcf7eb;border-radius:9px"><div class="eyebrow">Returned</div><div class="metric">${s.delivery.returned}<small> units</small></div></div></div>`:'<div class="help">Attach and verify POD before recording accepted/returned quantities.</div>'}<div class="buttons">${button('Attach POD','pod','',!s.dispatched?'disabled':'')}${button('Record delivery','delivery','primary',!s.dispatched||s.delivery?'disabled':'')}${button('Open return case','openReturn','',!s.delivery?.returned?'disabled':'')}</div></section><section class="card padded"><div class="row"><h2>Actual cost declaration</h2>${button('Record / update costs','costs','smallbtn',!s.dispatched||s.status==='Closed'?'disabled':'')}</div><p>Declare all components; zero means confirmed no charge.</p><div class="statlist">${[['freight','Freight'],['holding','Holding'],['unloading','Unloading'],['extras','Extras']].map(([k,l])=>`<div class="row"><span>${l}</span><b>${s.costs?money(s.costs[k]):'Not declared'}</b></div>`).join('')}<div class="line"></div><div class="row"><span>Total actual trip cost</span><b>${actual===null?'Not declared':money(actual)}</b></div></div></section></div><div class="stack">${shipmentSummary(s)}<section class="card padded"><h2>Cost variance</h2><p>Approved quoted freight versus actual freight. No trained prediction is claimed.</p><div class="statlist"><div class="row"><span>Frozen freight estimate</span><b>${money(s.estimate)}</b></div><div class="row"><span>Actual freight</span><b>${s.costs?money(s.costs.freight):'Not declared'}</b></div><div class="row"><span>Freight variance</span><b class="${v>0?'dangertext':''}">${v===null?'—':money(v)+' / '+(s.estimate?((v/s.estimate)*100).toFixed(1)+'%':'N/A')}</b></div></div><div class="help">Holding, unloading and extras are separate. All-in actual cost is not compared to a freight-only estimate.</div>${button('Close reconciled trip','closeTrip','primary',s.status==='Closed'?'disabled':'')}<p class="small muted" style="margin-top:12px">Demo policy: close linked customer returns before trip closure. Final business policy remains to be confirmed.</p></section></div></div>`;}
function audit(){return heading('Audit trail','Trace the decision, evidence and actor behind every change.',button(icon('download')+' Export events','exportAudit'))+`<section class="card"><div class="section-head"><h2>Recorded demonstration events</h2>${badge(`${state.events.length} events`,'gray')}</div>${state.events.map(e=>`<div class="audititem"><span class="avatar">${esc(e.actor.slice(0,2))}</span><div><b>${esc(e.action.replace(/([A-Z])/g,' $1'))} ${e.shipment?'· '+e.shipment:''}</b><p>${esc(e.detail)}</p><time>${new Date(e.time).toLocaleString('en-IN')} · ${esc(e.actor)} · ${esc(e.role)}</time></div></div>`).join('')}</section><div class="help">These local records can be edited by the device owner. They are not a tamper-proof server audit ledger.</div>`;}
function guide(){const cards=[['BUSINESS MODEL','Four parties, clear responsibility.','The principal owns goods and contracts the 3PL. The 3PL executes logistics; Amazon/Flipkart receive bulk orders. Transporters provide carriage. Principal and warehouse identities stay distinct.'],['SCOPE','Execute logistics, end to end.','Approved POs → grouping/trucks → departure appointment → scans → exceptions → documents → dispatch → POD/costs → customer returns. Procurement, vendor returns and full accounting are excluded.'],['CONTROL DESIGN','Urgency is not permission.','Short dispatch needs principal permission evidence plus manager approval. Scanner failure needs an independent checker and manager. Wrong SKU, missing documents and double stock issues stay blocked.'],['AI DISCLOSURE','Useful assistance, honestly labeled.','Drafts use templates; document checks and variance use rules. Live OpenAI assistance is available when the local AI server is configured and enabled. Templates remain clearly labeled fallbacks. Trained prediction, reinforcement learning and IoT are not implemented.'],['ARCHITECTURE','A browser-local working demonstration.','A pure ES-module engine separates business rules from the interface. State and small files persist in localStorage. AI requests use a loopback server with server-only credentials. Roles are simulated, not authenticated. This is not a production multi-user WMS.'],['PRODUCTION PATH','Before real operations.','Add server authentication, principal/warehouse isolation, transactional database, private files, durable audit, recovery, device mapping and confirmed accounting authority. No real stock or financial postings here. The local AI gateway is not production user authentication.'],['BUSINESS CASE','Measure outcomes, not invented ROI.','Measure wrong-SKU attempts caught, documentation completeness, planning time, exceptions, approval turnaround, on-time departure and comparable variance. Establish a baseline before claiming savings.'],['DEMONSTRATION','Show the exception, not just the happy path.','Demonstrate wrong SKU rejection, short pack held for evidence, independent scanner-failure reconciliation and return settlement. Explain why physical confirmation and data quality matter.']];return heading('Project guide','The operating model, design decisions and limitations—ready for an interview.',button(icon('arrow')+' Guided walkthrough','walkthrough','primary'))+`<div class="notice">${icon('help')}<span>Working demonstration, not production certification or a verified company case study. All sample entities and quantities are synthetic.</span></div><div class="guidegrid">${cards.map(([n,t,p],i)=>`<section class="card"><span class="number">${String(i+1).padStart(2,'0')} / ${n}</span><h3>${t}</h3><p>${p}</p></section>`).join('')}</div><section class="card padded" style="margin-top:20px"><div class="row"><div><h2>Your workspace</h2><p class="small muted">Export sample state or restart the walkthrough.</p></div><div class="buttons">${button('Export JSON','exportData')}${button('Reset demo data','reset','danger')}</div></div></section>`;}
function render(){const views={masters:()=>masterView(state,{heading,button,badge}),overview,planning,shipments,scanning,approvals,documents,returns:returnsPage,costs:costsPage,audit,guide};$('#app').innerHTML=shell((views[page]||overview)());bind();}
function go(p){page=p;render();window.scrollTo({top:0,behavior:'smooth'});}
function modal(title,body,onSubmit=null,submit='Save'){const m=$('#modal');m.innerHTML=`<form id="modalform"><header class="modalhead"><h2>${title}</h2><button type="button" class="close" aria-label="Close dialog">×</button></header><div class="modalbody"><div class="formerror" id="formerror" role="alert"></div>${body}</div><footer class="modalfoot"><button class="btn" type="button" data-close>Cancel</button>${onSubmit?`<button class="btn primary" type="submit">${submit}</button>`:''}</footer></form>`;m.querySelector('.close').onclick=()=>m.close();m.querySelector('[data-close]').onclick=()=>m.close();m.querySelector('form').onsubmit=async e=>{e.preventDefault();try{const obj=Object.fromEntries(new FormData(e.currentTarget));const ok=await onSubmit?.(obj,e.currentTarget);if(ok!==false)m.close();}catch(error){$('#formerror').textContent=error.message;}};m.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{m.close();actions(b.dataset.action,b.dataset);});m.showModal();}
function actionForm(title,body,type,transform=x=>x,submit='Save'){modal(title,body,p=>{const out=run(type,transform(p));if(out){toast('Recorded in the demonstration audit trail.');return true;}return false;},submit);}
function download(name,data,type='application/json'){const u=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function bind(){if($('#kpiAsOf'))$('#kpiAsOf').onchange=e=>{if(e.target.value&&e.target.value<=localToday()){serviceAsOf=e.target.value;render();}};if($('#directorPrincipal'))$('#directorPrincipal').onchange=e=>{directorFilters.principal=e.target.value;render();};if($('#directorWarehouse'))$('#directorWarehouse').onchange=e=>{directorFilters.warehouse=e.target.value;render();};if($('#mobilepage'))$('#mobilepage').onchange=e=>go(e.target.value);$$('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));$$('[data-open]').forEach(b=>b.onclick=()=>{activeShipment=b.dataset.open;go('scanning');});$('#role').onchange=e=>{role=e.target.value;render();toast('Demo role: '+role+'. This does not authenticate a user.');};if($('#shipselect'))$('#shipselect').onchange=e=>{activeShipment=e.target.value;render();};if($('#principalfilter'))$('#principalfilter').onchange=e=>{filterPrincipal=e.target.value;render();};if($('#warehousefilter'))$('#warehousefilter').onchange=e=>{filterWarehouse=e.target.value;render();};$$('.ordercheck').forEach(c=>c.onchange=()=>{c.checked?selected.add(c.value):selected.delete(c.value);render();});$('#global-search').onsubmit=e=>{e.preventDefault();globalSearch=new FormData(e.currentTarget).get('q');go('shipments');};if($('#scanform'))$('#scanform').onsubmit=e=>{e.preventDefault();if(run('scan',{code:new FormData(e.currentTarget).get('code')})){toast('Product identity verified.');$('#scan-code')?.focus();}};$$('[data-action]').forEach(b=>b.onclick=()=>actions(b.dataset.action,b.dataset));}
async function actions(a,attrs={}){if(a.startsWith('ai:')){try{const s=shipment();const options=a==='ai:plan'?{feature:'explain',orderIds:[...selected],truckId:$('input[name=truck]:checked')?.value,departure:$('#departure')?.value}:{feature:a==='ai:documents'?'documents':a==='ai:transporter'?'transporter':'explain',shipmentId:s.id};return await openCopilot({state,options,modal,getCurrentState:()=>state,onReview:review=>{const next=structuredClone(state);next.aiSuggestions=[...(next.aiSuggestions||[]),{...review,at:new Date().toISOString(),role}].slice(-25);next.events.unshift({id:'EV-AI-'+Date.now(),time:new Date().toISOString(),actor:role,role,shipment:options.shipmentId||'',action:'AI_REVIEW',detail:review.feature+' · '+review.provider+' · '+review.outcome});localStorage.setItem(VERSION,JSON.stringify(next));state=next;render();}});}catch(error){toast(error.message,true);return;}}if(a.startsWith('kpi:'))return serviceAction(a,attrs,{state,filters:directorFilters,asOf:serviceAsOf,modal,actionForm,field,textfield,button});if(a.startsWith('enh:'))return enhancementAction(a,attrs,{state,role,modal,actionForm,field,textfield,button,badge,filters:directorFilters,download,run});const s=shipment();
if(a==='goPlanning')return go('planning');if(a==='goDocuments')return go('documents');
if(a==='planningRules')return modal('Planning rules','<p>Only approved, stock-backed quantities are ready. Existing dispatches and active plan commitments are excluded. Grouping requires the same principal, source warehouse, destination, platform and category.</p><div class="help">Rates and dimensions are samples. Departure means warehouse dispatch day; ETA is a separate route estimate.</div>');
if(a==='confirmPlan'){const out=run('plan',{orders:[...selected],departure:$('#departure').value,truck:$('input[name=truck]:checked')?.value});if(out){activeShipment=out.result;selected.clear();go('scanning');toast('Departure plan created for the sample warehouse.');}return;}
if(a==='sampleCode'){let i=1;while(state.shipments.some(x=>x.scans.some(u=>u.code===`${s.lines[0].sku}-U-${String(i).padStart(4,'0')}`)))i++;$('#scan-code').value=`${s.lines[0].sku}-U-${String(i).padStart(4,'0')}`;$('#scan-code').focus();return;}
if(a==='packed')return actionForm('Revise packed quantity',`<p class="small muted" style="margin-bottom:17px">Changing quantity invalidates approvals. Documents must match the revised manifest.</p><div class="field"><label for="order">Order line</label><select id="order" name="order">${s.lines.map(l=>`<option value="${l.order}">${l.order} · ${l.sku} · planned ${l.planned}</option>`).join('')}</select></div>${field('Actual packed units','quantity',s.lines[0].packed,'number')}`,'setPacked',p=>({...p,quantity:Number(p.quantity)}));
if(a==='transport')return actionForm('Transport arrangement',`<div class="help">Manual handoff. Saving details does not book a carrier.</div>${field('Transporter','transporter',s.transporter)}${field('Vehicle registration','vehicle',s.vehicle)}${field('Driver name / reference','driver',s.driver)}`,'transport');
if(a==='seal')return actionForm('Seal and link carton / pallet',`<p class="small muted" style="margin-bottom:17px">Links unsealed scanned products. Aggregation does not increment product counts.</p>${field('Unique carton / pallet identifier','code',`CTN-${s.id}-01`)}<div class="help">CTN- for carton or PLT- for pallet. One packaging level is supported; nested packaging is future work.</div>`,'seal');
if(a==='requestPartial')return actionForm('Request partial dispatch',textfield('Shortfall, urgency, client impact and cost considerations','reason','','Principal permission evidence is required before manager approval.'),'requestPartial');
if(a==='rejectPartial')return actionForm('Manager: reject partial dispatch',textfield('Reason for holding or replanning','reason'),'rejectPartial',p=>p,'Record hold decision');
if(a==='approvePartial')return actionForm('Manager: approve partial dispatch',textfield('Decision and principal permission basis','reason','','Binds current quantities. Does not replace corrected documents.'),'approvePartial',p=>p,'Approve manifest');
if(a==='requestManual')return actionForm('Record scanner failure',textfield('Incident and physical evidence reference','reason','','Record failure, affected lines, last scan and independent count evidence.')+'<div class="help">Hold → independent checker → manager approval → reconciliation. Manual units stay labeled manual.</div>','requestManual');
if(a==='verifyManual')return actionForm('Checker: independent reconciliation',textfield('Identity, quantity and evidence checked','reason','','Use the Checker role. The warehouse requester cannot complete this step.'),'verifyManual');
if(a==='approveManual')return actionForm('Manager: manual scan exception',textfield('Approval reason and reconciliation reviewed','reason','','All other dispatch gates still apply.'),'approveManual',p=>p,'Approve exception');
if(a==='approvalEmail')return upload('approval');if(a==='pod')return upload('pod');if(a==='uploadDoc')return upload(attrs.kind);
if(a==='verifyDoc'){if(run('verifyDocument',{kind:attrs.kind}))toast('Document reviewed for current packed quantities.');return;}
if(a==='viewDoc'){const d=s.documents.find(d=>d.kind===attrs.kind);if(!d)return;return modal('Stored document',`<p><b>${esc(d.name)}</b><br>${esc(d.reference)}</p><div class="help">${d.sample?'SYNTHETIC SAMPLE — not an official invoice, email or POD.':'Local file. Presence is not independent proof of authenticity.'}</div><a class="btn primary" href="${esc(d.data)}" download="${esc(d.name)}">Download stored file</a>`);}
if(a==='draft')return modal('Transporter message draft',`<div class="notice">${icon('file')}Template · no live AI or external send</div><textarea aria-label="Editable transporter draft" id="drafttext" class="receipt" style="width:100%;min-height:300px">${esc(draft(state,s))}</textarea>`,()=>{download(`${s.id}-draft.txt`,$('#drafttext').value,'text/plain');return true;},'Download reviewed draft');
if(a==='dispatch')return modal('Confirm dispatch',`<p>Release <b>${total(s,'packed')} verified units</b> for <b>${s.id}</b>?</p><div class="help">Sample stock is issued once and actual departure recorded. No real warehouse is affected.</div>`,()=>{if(run('dispatch')){toast('Dispatched. Sample balances updated once.');return true;}return false;},'Confirm dispatch');
if(a==='delivery')return actionForm('Record delivery outcome',`<p class="small muted" style="margin-bottom:17px">Accepted + returned must equal ${total(s,'packed')} dispatched units. Verified POD required.</p>${s.lines.length===1?`<div class="formgrid">${field('Accepted units','accepted',total(s,'packed'),'number')}${field('Returned units','returned',0,'number')}</div>`:''}${deliveryFields(s,{field,textfield})}`,'delivery',p=>deliveryPayload(s,p));
if(a==='costs')return actionForm('Declare actual trip costs',`<div class="help">INR. Zero means no charge. No payment is executed.</div><div class="formgrid">${['freight','holding','unloading','extras'].map(k=>field(k[0].toUpperCase()+k.slice(1),'cost-'+k,s.costs?.[k]??(k==='freight'?s.estimate:0),'number').replace('step="1"','step="0.01"')).join('')}</div>`,'costs',p=>Object.fromEntries(['freight','holding','unloading','extras'].map(k=>[k,Number(p['cost-'+k])])));
if(a==='closeTrip'){if(run('closeTrip'))toast('Trip closed with obligations reconciled.');return;}
if(a==='openReturn'){const eligible=state.shipments.filter(x=>x.delivery?.returned>0);if(!eligible.length)return toast('Record a delivered shipment with returned quantities first.',true);return actionForm('Open linked customer return',`<div class="field"><label for="returnShipment">Source shipment</label><select id="returnShipment" name="shipment">${eligible.map(x=>`<option value="${x.id}">${x.id} · ${x.delivery.returned} returned units</option>`).join('')}</select></div>${field('Expected return units','quantity',1,'number')}${textfield('Return reason','reason')}`,'openReturn',p=>({...p,quantity:Number(p.quantity)}));}
if(a==='inspectReturn'){const r=state.returns.find(x=>x.id===attrs.return);return actionForm(`Receive & inspect ${r.id}`,`<div class="help">Expected ${r.expected} ${r.sku} units. Missing units do not restore stock.</div><div class="formgrid">${field('Usable units','usable',0,'number')}${field('Damaged / held units','damaged',0,'number')}${field('Missing units','missing',0,'number')}</div>`,'inspectReturn',p=>({...p,returnId:r.id,usable:Number(p.usable),damaged:Number(p.damaged),missing:Number(p.missing)}));}
if(a==='settleReturn'){const r=state.returns.find(x=>x.id===attrs.return),n=r.noteDraft;return actionForm(`Reconcile note for ${r.id}`,`<div class="help">Prepare and obtain manager approval for a credit/debit draft in the workbench below before reconciliation. No adjustment is also available with an explanation.</div><div class="field"><label for="noteType">Outcome</label><select id="noteType" name="noteType"><option ${n?.type==='Credit note'?'selected':''}>Credit note</option><option ${n?.type==='Debit note'?'selected':''}>Debit note</option><option>No adjustment</option></select></div>${field('Legal issuer / authorized entity','issuer',n?.issuer||principal(r.principal).name)}${field('Note / reconciliation reference','reference',n?.reference||'')}${field('Amount (INR)','amount',n?.total||0,'number').replace('step="1"','step="0.01"')}${textfield('Perspective, approval and settlement explanation','reason')}`,'settleReturn',p=>({...p,returnId:r.id,amount:Number(p.amount)}));}
if(a==='viewReturn'){const r=state.returns.find(x=>x.id===attrs.return);return modal(r.id+' · reconciled',`<p>${r.expected} expected · ${r.usable} usable · ${r.damaged} damaged · ${r.missing} missing</p><div class="help">${esc(r.note.type)} · ${esc(r.note.reference)}<br>Issuer: ${esc(r.note.issuer)}<br>Prepared by: 3PL · ${money(r.note.amount)}<br>${esc(r.note.reason)}</div>`);}
if(a==='walkthrough')return modal('Your interview walkthrough',`<ol style="padding-left:18px;line-height:2;font-size:12px"><li>Choose <b>Warehouse</b> role and SG-1041.</li><li>Record transporter, vehicle and driver.</li><li>Insert and verify ten sample unit codes; seal a carton.</li><li>Attach sample invoice, e-way and LR documents.</li><li>Switch to <b>Accounts</b> and verify each.</li><li>Switch to <b>Warehouse</b> and dispatch once.</li><li>Attach POD; verify as Accounts; record delivery as Warehouse.</li><li>Declare costs as Accounts; close as Manager.</li><li>Use SG-1042 for short-pack or scanner-failure exceptions.</li><li>Record returned goods, inspect as Checker and reconcile notes as Accounts.</li></ol><div class="help">Roles and data are simulated. No external messages or financial postings occur.</div>`);
if(a==='export')return download('last-mile-logistics-summary.csv','Shipment,Principal,Origin,Destination,Departure,Status,Planned,Packed\n'+state.shipments.map(s=>[s.id,principal(s.principal).name,wh(s.warehouse).name,s.destination,s.departure,s.status,total(s),total(s,'packed')].map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\n'),'text/csv');
if(a==='exportAudit')return download('last-mile-logistics-audit.json',JSON.stringify(state.events,null,2));if(a==='exportData')return download('last-mile-logistics-demo.json',JSON.stringify(state,null,2));
if(a==='reset')return modal('Reset this demonstration?',`<p>Clear only Last Mile Logistics sample records and files in this browser. Export first if you need the current journey.</p>`,()=>{state=seed();localStorage.setItem(VERSION,JSON.stringify(state));activeShipment=state.shipments[0].id;selected.clear();go('overview');toast('Sample workspace reset.');},'Reset workspace');
}
function upload(kind){const s=shipment(),label=doctypes.find(x=>x[0]===kind)?.[1]||kind;modal(`Attach ${label}`,`<div class="help">Synthetic files only, ≤ 1 MB. Upload a file or explicitly create a labeled sample. Sample evidence is not proof of a real transaction.</div>${field('Reference / email subject','reference',`${s.id}-${kind.toUpperCase()}`)}<div class="field"><label for="uploadfile">Local file (optional for a sample)</label><input type="file" id="uploadfile" name="file" accept=".pdf,.png,.jpg,.jpeg,.txt,.eml"><small>Stored in browser localStorage; total storage is limited.</small></div><label style="font-size:12px;display:flex;align-items:center;gap:8px"><input type="checkbox" name="sample" id="samplefile" checked>Create clearly labeled synthetic sample evidence</label>`,async(p,form)=>{let data,name,sample=false;const file=form.querySelector('#uploadfile').files[0];if(file?.size){if(file.size>1000000)throw Error('File is larger than 1 MB.');if(!/\.(pdf|png|jpe?g|txt|eml)$/i.test(file.name))throw Error('Unsupported type.');data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Read failed.'));r.readAsDataURL(file);});name=file.name;}else{if(!form.querySelector('#samplefile').checked)throw Error('Choose a file or explicitly create sample evidence.');sample=true;name=`SAMPLE-${s.id}-${kind}.txt`;data='data:text/plain;base64,'+btoa(String.fromCharCode(...new TextEncoder().encode(`SYNTHETIC DEMONSTRATION ONLY\n${label}\nShipment: ${s.id}\nReference: ${p.reference}\nPacked units: ${total(s,'packed')}\nNot an official invoice, permission email or POD.\n`)));}const out=run('document',{kind,reference:p.reference,data,name,sample});if(out){toast('Stored locally; verify where required.');return true;}return false;},'Attach evidence');}
render();
